INSERT INTO athkar_items(category, text_ar, translit, tr_fr, tr_en, reference, target, position, enabled)
SELECT $q$general$q$, $q$لَبَّيْكَ اللَّهُمَّ لَبَّيْكَ، لَبَّيْكَ لاَ شَرِيكَ لَكَ لَبَّيْكَ، إِنَّ الْحَمْدَ، وَالنِّعْمَةَ، لَكَ وَالْمُلْكَ، لاَ شَرِيكَ لَكَ$q$, $q$Labbayka llahoumma labbayka, labbayka la charika laka labbayka, inna l-hamda, wan-niʿmata, laka wal-moulka, la charika lak$q$, $q$Me voici, ô Allah, me voici ; me voici, Tu n’as aucun associé, me voici. Certes, la louange, le bienfait et la royauté T’appartiennent ; Tu n’as aucun associé. (talbiya du pèlerin en ‘umra ou en hajj)$q$, $q$$q$, $q$Hisn al-Muslim (Sa‘id al-Qahtani), « Talbiya du pèlerin », invocation n° 1. Al-Bukhari, Fath al-Bari 3/408 ; Muslim 2/841.$q$, 1, 900, false
WHERE NOT EXISTS (SELECT 1 FROM athkar_items WHERE category = $q$general$q$ AND text_ar = $q$لَبَّيْكَ اللَّهُمَّ لَبَّيْكَ، لَبَّيْكَ لاَ شَرِيكَ لَكَ لَبَّيْكَ، إِنَّ الْحَمْدَ، وَالنِّعْمَةَ، لَكَ وَالْمُلْكَ، لاَ شَرِيكَ لَكَ$q$);

INSERT INTO athkar_items(category, text_ar, translit, tr_fr, tr_en, reference, target, position, enabled)
SELECT $q$general$q$, $q$رَبَّنَا آتِنَا فِي الدُّنْيَا حَسَنَةً وَفِي الْآخِرَةِ حَسَنَةً وَقِنَا عَذَابَ النَّارِ$q$, $q$Rabbana atina fi d-dounya hasanatan wafi l-’akhirati hasanatan waqina ʿadhaba n-nar$q$, $q$Notre Seigneur, accorde-nous une belle part ici-bas et une belle part dans l’au-delà, et protège-nous du châtiment du Feu. (Coran 2:201 ; à dire entre le coin yéménite et la Pierre noire)$q$, $q$$q$, $q$Hisn al-Muslim (Sa‘id al-Qahtani), « Entre le coin yéménite et la Pierre noire », invocation n° 1. Abu Dawud 2/179 ; Ahmad 3/411 ; al-Baghawi, Sharh as-sunna 7/128 ; jugé hassan par al-Albani (Sahih Abi Dawud 1/354) ; le verset est tiré de sourate al-Baqara, 201.$q$, 1, 901, false
WHERE NOT EXISTS (SELECT 1 FROM athkar_items WHERE category = $q$general$q$ AND text_ar = $q$رَبَّنَا آتِنَا فِي الدُّنْيَا حَسَنَةً وَفِي الْآخِرَةِ حَسَنَةً وَقِنَا عَذَابَ النَّارِ$q$);

INSERT INTO athkar_items(category, text_ar, translit, tr_fr, tr_en, reference, target, position, enabled)
SELECT $q$general$q$, $q$لاَ إِلَهَ إِلاَّ اللَّهُ وَحْدَهُ لاَ شَرِيكَ لَهُ، لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ وَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ، لاَ إِلَهَ إِلاَّ اللَّهُ وَحْدَهُ، أَنْجَزَ وَعْدَهُ، وَنَصَرَ عَبْدَهُ، وَهَزَمَ الْأَحْزَابَ وَحْدَهُ$q$, $q$La ilaha illa llahou wahdahou la charika lahou, lahou l-moulkou walahou l-hamdou wahouwa ʿala koulli chay’in qadiroun, la ilaha illa llahou wahdahou, andjaza waʿdahou, wanasara ʿabdahou, wahazama l-ahzaba wahdah$q$, $q$Il n’y a de divinité qu’Allah, Seul, sans associé. À Lui la royauté, à Lui la louange, et Il est capable de toute chose. Il n’y a de divinité qu’Allah, Seul : Il a tenu Sa promesse, secouru Son serviteur et mis en déroute les coalisés à Lui seul. (le Prophète le disait trois fois sur as-Safa, en invoquant entre chaque fois, puis faisait de même sur al-Marwa)$q$, $q$$q$, $q$Hisn al-Muslim (Sa‘id al-Qahtani), « Sur as-Safa et al-Marwa », invocation n° 1. Muslim 2/888 (longue description du hajj du Prophète).$q$, 1, 902, false
WHERE NOT EXISTS (SELECT 1 FROM athkar_items WHERE category = $q$general$q$ AND text_ar = $q$لاَ إِلَهَ إِلاَّ اللَّهُ وَحْدَهُ لاَ شَرِيكَ لَهُ، لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ وَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ، لاَ إِلَهَ إِلاَّ اللَّهُ وَحْدَهُ، أَنْجَزَ وَعْدَهُ، وَنَصَرَ عَبْدَهُ، وَهَزَمَ الْأَحْزَابَ وَحْدَهُ$q$);

