SELECT $q$general$q$, $q$بِسْمِ اللَّهِ وَاللَّهُ أَكْبَرُ اللَّهُمَّ مِنْكَ وَلَكَ اللَّهُمَّ تَقَبَّلْ مِنِّي$q$, $q$Bismi llahi wallahou akbarou llahoumma minka walaka llahoumma taqabbal minni$q$, $q$Au nom d’Allah, Allah est le plus grand [Ô Allah, cela vient de Toi et c’est pour Toi]. Ô Allah, accepte-le de ma part. (à dire en égorgeant)$q$, $q$$q$, $q$Hisn al-Muslim (Sa‘id al-Qahtani), « À l’égorgement du sacrifice », invocation n° 1. Muslim 3/1557 ; al-Bayhaqi 9/287 (qui ajoute la partie entre crochets).$q$, 1, 907, false
WHERE NOT EXISTS (SELECT 1 FROM athkar_items WHERE category = $q$general$q$ AND text_ar = $q$بِسْمِ اللَّهِ وَاللَّهُ أَكْبَرُ اللَّهُمَّ مِنْكَ وَلَكَ اللَّهُمَّ تَقَبَّلْ مِنِّي$q$);

INSERT INTO athkar_items(category, text_ar, translit, tr_fr, tr_en, reference, target, position, enabled)
SELECT $q$general$q$, $q$أَعُوذُ بِكَلِمَاتِ اللَّهِ التَّامَّاتِ الَّتِي لاَ يُجَاوِزُهُنَّ بَرٌّ وَلاَ فَاجِرٌ: مِنْ شَرِّ مَا خَلَقَ، وَبَرَأَ وَذَرَأَ، وَمِنْ شَرِّ مَا يَنْزِلُ مِنَ السَّمَاءِ، وَمِنْ شَرِّ مَا يَعْرُجُ فِيهَا، وَمِنْ شَرِّ مَا ذَرَأَ فِي الْأَرْضِ، وَمِنْ شَرِّ مَا يَخْرُجُ مِنْهَا، وَمِنْ شَرِّ فِتَنِ اللَّيْلِ وَالنَّهَارِ، وَمِنْ شَرِّ كُلِّ طَارِقٍ إِلاَّ طَارِقاً يَطْرُقُ بِخَيْرٍ يَا رَحْمَنُ$q$, $q$Aʿoudhou bikalimati llahi t-tammati-llati la youdjawizouhounna barroun wala fadjiroun, min charri ma khalaqa, wabara’a wadhara’a, wamin charri ma yanzilou mina s-sama’i, wamin charri ma yaʿroudjou fiha, wamin charri ma dhara’a fi l-ardi, wamin charri ma yakhroudjou minha, wamin charri fitani llayli wan-nahari, wamin charri koulli tariqin illa tariqan yatrouqou bikhayrin ya rahman$q$, $q$Je cherche refuge dans les paroles parfaites d’Allah, que ni le pieux ni le pervers ne peuvent transgresser : contre le mal de ce qu’Il a créé, façonné et fait naître ; contre le mal de ce qui descend du ciel et de ce qui y monte ; contre le mal de ce qu’Il a fait naître sur la terre et de ce qui en sort ; contre le mal des épreuves de la nuit et du jour, et le mal de tout visiteur nocturne, sauf celui qui vient avec du bien, ô Tout-Miséricordieux.$q$, $q$$q$, $q$Hisn al-Muslim (Sa‘id al-Qahtani), « Contre les démons rebelles », invocation n° 1. Ahmad 3/419, chaîne authentique ; Ibn as-Sunni n° 637 ; Majma‘ az-zawa’id 10/127. La dernière phrase est rapportée par le sens d’après Muslim.$q$, 1, 908, false
WHERE NOT EXISTS (SELECT 1 FROM athkar_items WHERE category = $q$general$q$ AND text_ar = $q$أَعُوذُ بِكَلِمَاتِ اللَّهِ التَّامَّاتِ الَّتِي لاَ يُجَاوِزُهُنَّ بَرٌّ وَلاَ فَاجِرٌ: مِنْ شَرِّ مَا خَلَقَ، وَبَرَأَ وَذَرَأَ، وَمِنْ شَرِّ مَا يَنْزِلُ مِنَ السَّمَاءِ، وَمِنْ شَرِّ مَا يَعْرُجُ فِيهَا، وَمِنْ شَرِّ مَا ذَرَأَ فِي الْأَرْضِ، وَمِنْ شَرِّ مَا يَخْرُجُ مِنْهَا، وَمِنْ شَرِّ فِتَنِ اللَّيْلِ وَالنَّهَارِ، وَمِنْ شَرِّ كُلِّ طَارِقٍ إِلاَّ طَارِقاً يَطْرُقُ بِخَيْرٍ يَا رَحْمَنُ$q$);

INSERT INTO athkar_items(category, text_ar, translit, tr_fr, tr_en, reference, target, position, enabled)
SELECT $q$general$q$, $q$أَسْتَغْفِرُ اللَّهَ الْعَظِيمَ الَّذِي لاَ إِلَهَ إِلاَّ هُوَ الْحَيُّ الْقَيُّومُ وَأَتُوبُ إِلَيْهِ$q$, $q$Astaghfirou llaha l-ʿadhima-lladhi la ilaha illa houwa l-hayyou l-qayyoumou wa’atoubou ilayh$q$, $q$Je demande pardon à Allah, l’Immense, il n’y a de divinité que Lui, le Vivant, Celui qui subsiste par Lui-même, et je me repens à Lui. (hadith : celui qui le dit, Allah lui pardonne, même s’il a fui le combat)$q$, $q$$q$, $q$Hisn al-Muslim (Sa‘id al-Qahtani), « Demander pardon à Allah », invocation n° 1. Abu Dawud 2/85 ; at-Tirmidhi 5/569 ; al-Hakim 1/511 (jugé authentique, adh-Dhahabi d’accord) ; Sahih at-Tirmidhi 3/182.$q$, 1, 909, false
WHERE NOT EXISTS (SELECT 1 FROM athkar_items WHERE category = $q$general$q$ AND text_ar = $q$أَسْتَغْفِرُ اللَّهَ الْعَظِيمَ الَّذِي لاَ إِلَهَ إِلاَّ هُوَ الْحَيُّ الْقَيُّومُ وَأَتُوبُ إِلَيْهِ$q$);

INSERT INTO athkar_items(category, text_ar, translit, tr_fr, tr_en, reference, target, position, enabled)
