INSERT INTO athkar_items(category, text_ar, translit, tr_fr, tr_en, reference, target, position, enabled)
SELECT $q$general$q$, $q$لاَ إِلَهَ إِلاَّ اللَّهُ وَحْدَهُ لاَ شَرِيكَ لَهُ، لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ وَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ$q$, $q$La ilaha illa llahou wahdahou la charika lahou, lahou l-moulkou walahou l-hamdou wahouwa ʿala koulli chay’in qadir$q$, $q$Il n’y a de divinité qu’Allah, Seul, sans associé. À Lui la royauté, à Lui la louange, et Il est capable de toute chose. (hadith : celui qui le dit dix fois est comme celui qui a affranchi quatre âmes parmi les descendants d’Ismaël)$q$, $q$$q$, $q$Hisn al-Muslim (Sa‘id al-Qahtani), « Mérite de la glorification, de la louange, de l’unicité et du takbir », invocation n° 2. Al-Bukhari 7/67 ; Muslim 4/2071. Le même texte est dit le jour de ‘Arafa (at-Tirmidhi, jugé hassan : « la meilleure invocation est celle du jour de ‘Arafa, et le meilleur de ce que j’ai dit, moi et les prophètes avant moi »).$q$, 10, 911, false
WHERE NOT EXISTS (SELECT 1 FROM athkar_items WHERE category = $q$general$q$ AND text_ar = $q$لاَ إِلَهَ إِلاَّ اللَّهُ وَحْدَهُ لاَ شَرِيكَ لَهُ، لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ وَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ$q$);

INSERT INTO athkar_items(category, text_ar, translit, tr_fr, tr_en, reference, target, position, enabled)
SELECT $q$general$q$, $q$سُبْحَانَ اللَّهِ وَبِحَمْدِهِ، سُبْحَانَ اللَّهِ الْعَظِيمِ$q$, $q$Soubhana llahi wabihamdihi, soubhana llahi l-ʿadhim$q$, $q$Gloire à Allah et par Sa louange ; gloire à Allah, l’Immense. (hadith : deux paroles légères sur la langue, lourdes dans la balance, aimées du Tout-Miséricordieux)$q$, $q$$q$, $q$Hisn al-Muslim (Sa‘id al-Qahtani), « Mérite de la glorification, de la louange, de l’unicité et du takbir », invocation n° 3. Al-Bukhari 7/167 ; Muslim 4/2072.$q$, 1, 912, false
