INSERT INTO athkar_items(category, text_ar, translit, tr_fr, tr_en, reference, target, position, enabled)
SELECT $q$general$q$, $q$سُبْحَانَ اللَّهِ، وَالْحَمْدُ لِلَّهِ، وَلاَ إِلَهَ إِلاَّ اللَّهُ، وَاللَّهُ أَكْبَرُ$q$, $q$Soubhana llahi, wal-hamdou lillahi, wala ilaha illa llahou, wallahou akbar$q$, $q$Gloire à Allah, louange à Allah, il n’y a de divinité qu’Allah, et Allah est le plus grand. (hadith : « Les dire m’est plus cher que tout ce sur quoi le soleil se lève »)$q$, $q$$q$, $q$Hisn al-Muslim (Sa‘id al-Qahtani), « Mérite de la glorification, de la louange, de l’unicité et du takbir », invocation n° 4. Muslim 4/2072.$q$, 1, 913, false
WHERE NOT EXISTS (SELECT 1 FROM athkar_items WHERE category = $q$general$q$ AND text_ar = $q$سُبْحَانَ اللَّهِ، وَالْحَمْدُ لِلَّهِ، وَلاَ إِلَهَ إِلاَّ اللَّهُ، وَاللَّهُ أَكْبَرُ$q$);

INSERT INTO athkar_items(category, text_ar, translit, tr_fr, tr_en, reference, target, position, enabled)
SELECT $q$general$q$, $q$سُبْحَانَ اللَّهِ الْعَظِيمِ وَبِحَمْدِهِ$q$, $q$Soubhana llahi l-ʿadhimi wabihamdih$q$, $q$Gloire à Allah, l’Immense, et par Sa louange. (hadith : un palmier est planté au Paradis pour celui qui le dit)$q$, $q$$q$, $q$Hisn al-Muslim (Sa‘id al-Qahtani), « Mérite de la glorification, de la louange, de l’unicité et du takbir », invocation n° 5. At-Tirmidhi 5/511 ; al-Hakim 1/501, jugé authentique, adh-Dhahabi d’accord (Sahih al-Jami‘ 5/531 ; Sahih at-Tirmidhi 3/160).$q$, 1, 914, false
