INSERT INTO athkar_items(category, text_ar, translit, tr_fr, tr_en, reference, target, position, enabled)
SELECT $q$general$q$, $q$لاَ إِلَهَ إِلاَّ اللَّهُ وَحْدَهُ لاَ شَرِيكَ لَهُ، اللَّهُ أَكْبَرُ كَبِيراً، وَالْحَمْدُ لِلَّهِ كَثِيراً، سُبْحَانَ اللَّهِ رَبِّ الْعَالَمِينَ، لاَ حَوْلَ وَلاَ قُوَّةَ إِلاَّ بِاللَّهِ الْعَزِيزِ الْحَكِيمِ$q$, $q$La ilaha illa llahou wahdahou la charika lahou, Allahou akbarou kabiran, wal-hamdou lillahi kathiran, soubhana llahi rabbi l-ʿalamina, la hawla wala qouwwata illa billahi l-ʿazizi l-hakim$q$, $q$Il n’y a de divinité qu’Allah, Seul, sans associé. Allah est le plus grand, d’une grandeur parfaite ; louange à Allah, abondante ; gloire à Allah, Seigneur des mondes ; il n’y a de force ni de puissance qu’en Allah, le Puissant, le Sage. (enseigné à un bédouin qui demandait des paroles à dire)$q$, $q$$q$, $q$Hisn al-Muslim (Sa‘id al-Qahtani), « Mérite de la glorification, de la louange, de l’unicité et du takbir », invocation n° 7. Muslim 4/2072 ; Abu Dawud ajoute : « Il a rempli ses mains de bien » (1/220).$q$, 1, 916, false
WHERE NOT EXISTS (SELECT 1 FROM athkar_items WHERE category = $q$general$q$ AND text_ar = $q$لاَ إِلَهَ إِلاَّ اللَّهُ وَحْدَهُ لاَ شَرِيكَ لَهُ، اللَّهُ أَكْبَرُ كَبِيراً، وَالْحَمْدُ لِلَّهِ كَثِيراً، سُبْحَانَ اللَّهِ رَبِّ الْعَالَمِينَ، لاَ حَوْلَ وَلاَ قُوَّةَ إِلاَّ بِاللَّهِ الْعَزِيزِ الْحَكِيمِ$q$);

INSERT INTO athkar_items(category, text_ar, translit, tr_fr, tr_en, reference, target, position, enabled)
SELECT $q$general$q$, $q$اللَّهُمَّ اغْفِرْ لِي، وَارْحَمْنِي، وَاهْدِنِي، وَارْزُقْنِي$q$, $q$Allahoumma-ghfir li, warhamni, wahdini, warzouqni$q$, $q$Ô Allah, pardonne-moi, fais-moi miséricorde, guide-moi et pourvois à mes besoins. (réponse du Prophète au bédouin qui demandait ce qu’il y avait pour lui)$q$, $q$$q$, $q$Hisn al-Muslim (Sa‘id al-Qahtani), « Mérite de la glorification, de la louange, de l’unicité et du takbir », invocation n° 8. Muslim 4/2072.$q$, 1, 917, false
WHERE NOT EXISTS (SELECT 1 FROM athkar_items WHERE category = $q$general$q$ AND text_ar = $q$اللَّهُمَّ اغْفِرْ لِي، وَارْحَمْنِي، وَاهْدِنِي، وَارْزُقْنِي$q$);

INSERT INTO athkar_items(category, text_ar, translit, tr_fr, tr_en, reference, target, position, enabled)
SELECT $q$general$q$, $q$اللَّهُمَّ اغْفِرْ لِي، وَارْحَمْنِي، وَاهْدِنِي، وَعَافِنِي وَارْزُقْنِي$q$, $q$Allahoumma-ghfir li, warhamni, wahdini, waʿafini warzouqni$q$, $q$Ô Allah, pardonne-moi, fais-moi miséricorde, guide-moi, accorde-moi la santé et pourvois à mes besoins. (que le Prophète faisait dire, après la prière, à celui qui se convertissait à l’islam)$q$, $q$$q$, $q$Hisn al-Muslim (Sa‘id al-Qahtani), « Mérite de la glorification, de la louange, de l’unicité et du takbir », invocation n° 9. Muslim 4/2073.$q$, 1, 918, false
WHERE NOT EXISTS (SELECT 1 FROM athkar_items WHERE category = $q$general$q$ AND text_ar = $q$اللَّهُمَّ اغْفِرْ لِي، وَارْحَمْنِي، وَاهْدِنِي، وَعَافِنِي وَارْزُقْنِي$q$);
